  const filteredGuests = event.guests.filter(g => (filter === 'All' || g.rsvp === filter) && `${g.name} ${g.dietary} ${g.bringing}`.toLowerCase().includes(query.toLowerCase()));
  const filteredGroceries = event.groceries.filter(g => (filter === 'All' || g.status === filter) && `${g.name} ${g.store}`.toLowerCase().includes(query.toLowerCase()));
